# Every piece of code belongs to exactly one module

## Concern

Which module owns each non-test Go file, so every concern has one home and no
code sits outside a boundary.

## Decision

- Every non-test Go file matching `space` lies in the `home` of exactly one
  module (a `module.yaml`).
- Module homes do not overlap.
- Each module states its concern in the `concern:` line of its `module.yaml`.
  No two modules' `concern:` lines name the same responsibility, whether
  under different words or with one split across two modules.
- A module's `home` holds only code of its `concern:`. A file belongs to
  another concern when its main responsibility is what another module's
  `concern:` line names.
- Both are judged when a `module.yaml` is added or changed, against every
  other module's `concern:`, `home` and the files each `home` glob matches.
- Code matching `exceptions` belongs to no module; nothing new is added there.
package runner

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/sloprail/harness-mocks/claude-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/claude-mock/internal/toolexec"
	"github.com/sloprail/harness-mocks/internal/procexec"
	"github.com/sloprail/harness-mocks/internal/tasks"
)

// tasksDir is where a session's background task output lives, as real Claude
// Code lays it out: <tmp>/claude-<uid>/<encoded cwd>/<session>/tasks, with
// <tmp> CLAUDE_CODE_TMPDIR or /tmp (the 2.1.282 binary's temp-root function),
// symlinks resolved (real receipts name /private/tmp/… on macOS).
func tasksDir(cwd, sessionID string) string {
	base := os.Getenv("CLAUDE_CODE_TMPDIR")
	if base == "" {
		base = "/tmp"
	}
	root := filepath.Join(base, "claude-"+strconv.Itoa(os.Getuid()))
	_ = os.MkdirAll(root, 0o700)
	if resolved, err := filepath.EvalSymlinks(root); err == nil {
		root = resolved
	}
	encoded := nonAlphanumRe.ReplaceAllString(resolveEncodingCwd(cwd), "-")
	return filepath.Join(root, encoded, sessionID, "tasks")
}

// exitTrailer is what Claude Code appends to a background command's output file
// when it ends: how it ended.
func exitTrailer(code int, killed bool) string {
	if killed {
		return "\n[killed]\n"
	}
	return fmt.Sprintf("\n[exited with code %d]\n", code)
}

// launchBash starts a background Bash for owner and returns its receipt. Inside
// a foreground sub-agent (cfg.SyncSubagent) the receipt says the command is
// terminated at the sub-agent's final response, as real Claude Code's does.
//
// sr:provides background-bash/claude
// sr:provides foreground-subagent-bash-ends-with-response/claude
func (b *backgroundTasks) launchBash(cfg Config, toolUseID string, raw json.RawMessage) toolexec.Result {
	var in struct {
		Command     string `json:"command"`
		Description string `json:"description"`
	}
	if err := json.Unmarshal(raw, &in); err != nil || in.Command == "" {
		return inputValidationError("Bash", []string{"command"})
	}
	id := "b" + randomID(8)
	dir := tasksDir(cfg.Cwd, cfg.SessionID)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return toolexec.Result{Output: fmt.Sprintf("Bash: %v", err), IsError: true}
	}
	outFile := filepath.Join(dir, id+".output")
	out, err := os.Create(outFile)
	if err != nil {
		return toolexec.Result{Output: fmt.Sprintf("Bash: %v", err), IsError: true}
	}
	desc := in.Description
	if desc == "" {
		desc = in.Command
	}
	task := tasks.NewTask(tasks.Command, id)
	task.ToolUseID, task.Owner, task.Description, task.Command, task.OutputFile = toolUseID, cfg.AgentID, desc, in.Command, outFile
	task.Meta = taskStart{ID: id, ToolUseID: toolUseID, Description: desc, TaskType: "local_bash", Backgrounded: true}
	frames := frameObserver{cfg}
	if err := b.StartCommand(task, tasks.CommandSpec{
		Argv: []string{"/bin/sh", "-c", in.Command}, Dir: cfg.Cwd,
		Env: procexec.Env(os.Environ(), childenv.Identity(cfg.SessionID), childenv.Defaults()),
		Out: out, Trailer: exitTrailer,
		Started: func(t *tasks.Task) { tasks.Announce(b.Registry, t, frames) },
		Ended:   func(t *tasks.Task) { tasks.Conclude(b.Registry, t, frames) },
	}); err != nil {
		return toolexec.Result{Output: fmt.Sprintf("Bash: %v", err), IsError: true}
	}

	endsWithFinal := cfg.SyncSubagent
	parts := []string{"Command running in background with ID: " + id + ". Output is being written to: " + outFile + "."}
	if endsWithFinal {
		parts = append(parts, "If it exits while you are still working you will be notified, but it is terminated when you give your final response and no notification can follow that — so do not end your turn to wait for it; if you need its result, wait for it before giving your final response.")
	} else {
		parts = append(parts, "You will be notified when it completes.")
	}
	parts = append(parts, "To check interim output, use Read on that file path.")
	text := strings.Join(parts, " ")
	tur := map[string]any{
		"stdout": "", "stderr": "", "interrupted": false, "isImage": false, "noOutputExpected": false,
		"backgroundTaskId": id,
	}
	if endsWithFinal {
		tur["backgroundEndsWithFinalResponse"] = true
	}
	if changesDirectory(in.Command) {
		hint := "Session cwd remains " + cfg.Cwd + "; directory changes made by the backgrounded command do not apply to subsequent commands."
		text += "\n" + hint
		tur["backgroundCwdHint"] = hint
	}
	return toolexec.Result{Output: text, ToolUseResult: tur}
}

package runner

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
	"github.com/sloprail/harness-mocks/internal/tools"
)

// toolName is how hooks name the shell tool.
const toolName = "Bash"

// toolHost is Codex's side of a tool call: one shell tool, its hooks, and
// the words it tells the agent in.
type toolHost struct{ *state }

// Tool: the one tool the mock runs is the shell, which needs a command.
func (h toolHost) Tool(name string) ([]string, bool) { return []string{"command"}, name == toolName }

func command(c toolcall.Call) string {
	var in struct {
		Command string `json:"command"`
	}
	_ = json.Unmarshal(c.Input, &in)
	return in.Command
}

func (h toolHost) payload(c toolcall.Call) map[string]any {
	return map[string]any{"turn_id": h.turnID, "tool_name": toolName, "tool_use_id": c.ID,
		"tool_input": map[string]string{"command": command(c)}}
}

// Before fires PreToolUse and asks for the refusal of what the hooks decided.
func (h toolHost) Before(ctx context.Context, c toolcall.Call) (bool, string) {
	var ds []hooks.Decision
	for _, o := range h.hooks.Fire(ctx, hooks.PreToolUse, toolName, h.payload(c)) {
		ds = append(ds, hooks.Interpret(hooks.PreToolUse, o))
	}
	return hooks.Refusal(ds)
}

// Execute runs the command and shows it in the event stream.
func (h toolHost) Execute(ctx context.Context, c toolcall.Call) toolcall.Result {
	cmd := command(c)
	id := h.events.CommandStarted(cmd)
	r := tools.Bash(ctx, cmd, h.cfg.Cwd, h.toolEnv)
	h.events.CommandCompleted(id, cmd, r.Output, r.ExitCode)
	return toolcall.Result{Output: r.Output, Failed: r.Failed()}
}

// After fires PostToolUse, which Codex fires for every command that ran,
// whatever its exit status; a hook that blocks (exit 2, or a block decision)
// gives the agent its feedback in place of the result.
// sr:provides posttooluse-payload/codex
func (h toolHost) After(ctx context.Context, c toolcall.Call, r toolcall.Result, _ corehooks.AfterTool) (string, bool) {
	own := h.payload(c)
	own["tool_response"] = r.Output
	for _, o := range h.hooks.Fire(ctx, hooks.PostToolUse, toolName, own) {
		d := hooks.Interpret(hooks.PostToolUse, o)
		if d.Context != "" {
			h.rollout.Developer(d.Context)
		}
		switch {
		case d.Blocked:
			return d.BlockReason, true
		case d.Denied:
			return d.DenyReason, true
		}
	}
	return "", false
}

// Answer records what the agent was told, in Codex's words.
func (h toolHost) Answer(c toolcall.Call, a toolcall.Answer) {
	var text string
	switch a.Kind {
	case toolcall.Unknown:
		text = "unsupported call: " + c.Name
	case toolcall.Invalid:
		text = fmt.Sprintf("failed to parse function arguments: missing field `%s`", a.Missing[0])
	case toolcall.Refused:
		text = fmt.Sprintf("Command blocked by PreToolUse hook: %s. Command: %s", a.Reason, command(c))
		fmt.Fprintf(h.cfg.Stderr, "ERROR codex_core::tools::router: error=%s\n", text)
	case toolcall.Done:
		text = a.Result.Output
		if a.Replaced {
			text = a.Feedback
			fmt.Fprintf(h.cfg.Stderr, "ERROR codex_core::tools::router: error=%s\n", text)
		}
	}
	h.rollout.ToolOutput(c.ID, text)
}
package toolexec

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/internal/tools"
)

// shell runs a Shell call. A command exiting non-zero failed, whatever its
// status (grep finding nothing is a failure too): the result is a failure
// carrying the exit code and both streams, and the failure hook's
// error_message is what the command printed, or else "Command failed with
// exit code N" (recorded: runs/tool-failure, runs/shell-exit-status).
//
// sr:provides bash-tool-result/cursor
// sr:docs https://cursor.com/docs/hooks#aftershellexecution
func shell(ctx context.Context, c Call, dir string, env []string) Result {
	cwd := dir
	if wd := c.str("workingDirectory"); wd != "" {
		cwd = wd
	}
	start := time.Now()
	res := tools.Bash(ctx, c.Command(), cwd, env)
	took := time.Since(start)
	body := map[string]any{
		"command": c.Command(), "workingDirectory": c.str("workingDirectory"), "exitCode": res.ExitCode, "signal": "",
		"stdout": res.Stdout, "stderr": res.Stderr, "executionTime": took.Milliseconds(), "interleavedOutput": res.Output,
	}
	r := Result{Output: res.Output, Took: took, ToolOutput: jsonString(struct {
		Output   string `json:"output"`
		ExitCode int    `json:"exitCode"`
	}{res.Output, res.ExitCode})}
	if !res.Failed() {
		r.Frame = map[string]any{"success": body, "isBackground": false}
		return r
	}
	body["aborted"] = false
	r.Failed, r.Frame = true, map[string]any{"failure": body, "isBackground": false}
	r.ErrorMessage = strings.TrimSpace(res.Output)
	if r.ErrorMessage == "" {
		r.ErrorMessage = fmt.Sprintf("Command failed with exit code %d", res.ExitCode)
	}
	return r
}
