// DefaultWaitCeiling is how long a non-interactive run waits idle for background
// agents after its final turn before it stops waiting.
const DefaultWaitCeiling = 10 * time.Minute

// WaitCeiling is ctx limited to ceiling of idle waiting: past it the wait ends and
// what still runs is dropped (Shutdown). A ceiling of zero or less is no limit.
// Idle waiting starts over each time the agent takes a turn to handle a result, so
// each wait gets its own.
func WaitCeiling(ctx context.Context, ceiling time.Duration) (context.Context, context.CancelFunc) {
	if ceiling <= 0 {
		return context.WithCancel(ctx)
	}
	return context.WithTimeout(ctx, ceiling)
}
package tasks

import "context"

// TakeFinished claims, in launch order, every finished task owner launched that
// has not been handed over yet: what an owner that is still working is told
// inside its turn, after its next tool result.
//
// sr:capability task-notifications
func (r *Registry) TakeFinished(owner string) []*Task {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []*Task
	for _, t := range r.tasks {
		if t.Owner == owner && !t.delivered && t.Finished() {
			t.delivered = true
			out = append(out, t)
		}
	}
	return out
}

// AwaitAfterTurn is what a non-interactive session does once a turn has ended:
// it returns the next finished task of owner, to start a further turn, waiting
// while owner still has a background agent running. It returns nil when there
// is nothing left to wait for.
//
// sr:capability print-waits-for-background-agents
func (r *Registry) AwaitAfterTurn(ctx context.Context, owner string) *Task {
	for {
		if t := r.takeFirstFinished(owner); t != nil {
			return t
		}
		if !r.AgentsRunning(owner) {
			return nil
		}
		select {
		case <-r.changed:
		case <-ctx.Done():
			return nil
		}
	}
}

// NextTurn is the next task to hand owner as a turn of its own that accept lets
// through: a notification a prompt hook refuses starts no turn, and the next
// finished task is handed over instead.
func (r *Registry) NextTurn(ctx context.Context, owner string, accept func(*Task) bool) *Task {
	for t := r.AwaitAfterTurn(ctx, owner); t != nil; t = r.AwaitAfterTurn(ctx, owner) {
		if accept(t) {
			return t
		}
	}
	return nil
}

func (r *Registry) takeFirstFinished(owner string) *Task {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, t := range r.tasks {
		if t.Owner == owner && !t.delivered && t.Finished() {
			t.delivered = true
			return t
		}
	}
	return nil
}
package tasks

// Observer is told what a run's stream announces of a task: that the set of
// running background tasks changed, that a task started, how its status was
// updated when it ended, and its end notification. How each is written is the
// harness's.
type Observer interface {
	// Changed is the background tasks running now, told when one joins or leaves
	// them: before a task's start is announced, and before its end is.
	Changed(running []*Task)
	Started(*Task)
	// Updated is the end status the task's update reports: "killed" for a
	// command the harness ended, else the task's own status.
	Updated(t *Task, status string)
	Notified(*Task)
}

// Announce reports that a task started (a background task or a sub-agent): first
// the running set it joins, when it is one of the registry's background tasks (a
// foreground sub-agent is not), then the start.
func Announce(r *Registry, t *Task, o Observer) {
	if r.has(t.ID) {
		o.Changed(r.Running())
	}
	o.Started(t)
}

// Conclude reports a task's end: the running set without it, when it is one of the
// registry's background tasks, then its status update, then its notification.
//
// sr:capability task-stream-frames
func Conclude(r *Registry, t *Task, o Observer) {
	if r.has(t.ID) {
		var rest []*Task
		for _, other := range r.Running() {
			if other.ID != t.ID {
				rest = append(rest, other)
			}
		}
		o.Changed(rest)
	}
	updated := string(t.Status())
	if t.Killed() {
		updated = "killed"
	}
	o.Updated(t, updated)
	o.Notified(t)
}
package tasks

import "time"

// stopOwned kills the commands owner still has running, marks them handed over
// (a killed command is reported on the stream only) and waits for them to be
// gone. Agents are not killed.
func (r *Registry) stopOwned(owner string) {
	if r == nil {
		return
	}
	r.mu.Lock()
	var victims []*Task
	for _, t := range r.tasks {
		if t.Owner == owner && t.Kind == Command && !t.Finished() {
			t.killed.Store(true)
			t.delivered = true
			victims = append(victims, t)
		}
	}
	r.mu.Unlock()
	for _, t := range victims {
		t.kill()
		<-t.done
	}
}

// EndOfResponse ends what a foreground sub-agent still has running when it
// gives its final response: its background commands are terminated.
//
// sr:capability foreground-subagent-bash-ends-with-response
func (r *Registry) EndOfResponse(owner string) { r.stopOwned(owner) }

// ReapAtExit ends what owner still has running when a non-interactive run's
// other work is done: its background commands are terminated, once grace has
// passed, so that a command that finishes right after the final result still
// delivers its output.
//
// sr:capability background-bash-reaped-at-exit
func (r *Registry) ReapAtExit(owner string, grace time.Duration) {
	if r == nil {
		return
	}
	r.mu.Lock()
	var running []*Task
	for _, t := range r.tasks {
		if t.Owner == owner && t.Kind == Command && !t.Finished() {
			running = append(running, t)
		}
	}
	r.mu.Unlock()
	timeout := time.After(grace)
	for _, t := range running {
		select {
		case <-t.done:
		case <-timeout:
			r.stopOwned(owner)
			return
		}
	}
}

// Shutdown ends the whole session's background work when the run returns: it
// kills every running command, cancels the registry's context (and so running
// background agents) and waits for all of it.
func (r *Registry) Shutdown() {
	if r == nil {
		return
	}
	r.mu.Lock()
	var kills []func()
	for _, t := range r.tasks {
		if t.Kind == Command && !t.Finished() {
			t.killed.Store(true)
			kills = append(kills, t.kill)
		}
	}
	r.mu.Unlock()
	for _, kill := range kills {
		kill()
	}
	r.cancel()
	r.wg.Wait()
}
