package runner

import (
	"context"
	"math/rand"
	"os"
	"path/filepath"
	"strconv"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	"github.com/sloprail/harness-mocks/internal/procexec"
	"github.com/sloprail/harness-mocks/internal/tasks"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/childenv"
)

// background is a run's background shell commands (recorded:
// runs/background-bash-start): the registry that runs them and, in launch
// order, the tasks it has started.
type background struct {
	reg      *tasks.Registry
	launched []*tasks.Task
}

func newBackground() *background { return &background{reg: tasks.NewRegistry()} }

// launchBackground starts a Shell call that asked to run in the background and
// answers it at once: the call succeeds with the shell id and pid of the
// command, which keeps running while the agent works, and whose output goes to
// <terminals>/<shell id>.txt beside the conversation's project folder. The
// call fires no afterShellExecution, and its postToolUse hook is told
// {"shell_id","pid"}.
//
// sr:provides background-bash/cursor
func (s *session) launchBackground(c toolexec.Call) toolexec.Result {
	start := time.Now()
	id := 100000 + rand.Intn(900000)
	dir := filepath.Join(filepath.Dir(filepath.Dir(filepath.Dir(s.tr.path))), "terminals")
	_ = os.MkdirAll(dir, 0o755)
	file := filepath.Join(dir, strconv.Itoa(id)+".txt")
	out, err := os.Create(file)
	if err != nil {
		return toolexec.Result{Failed: true, ErrorMessage: err.Error(), Output: err.Error(),
			Frame: map[string]any{"error": map[string]any{"errorMessage": err.Error()}}}
	}
	t := tasks.NewTask(tasks.Command, strconv.Itoa(id))
	t.Command, t.Description, t.OutputFile = c.Command(), c.Command(), file
	err = s.bg.reg.StartCommand(t, tasks.CommandSpec{
		Argv: []string{"/bin/sh", "-c", c.Command()}, Dir: s.cfg.Dir, Out: out,
		Env: procexec.Env(s.cfg.Environ, childenv.Identity(s.id), childenv.Defaults()),
	})
	if err != nil {
		return toolexec.Result{Failed: true, ErrorMessage: err.Error(), Output: err.Error(),
			Frame: map[string]any{"error": map[string]any{"errorMessage": err.Error()}}}
	}
	s.bg.launched = append(s.bg.launched, t)
	took := time.Since(start)
	return toolexec.Result{Took: took,
		ToolOutput: jsonLine(map[string]any{"shell_id": id, "pid": t.Pid}).String(),
		Frame: map[string]any{"success": map[string]any{
			"command": c.Command(), "workingDirectory": "", "exitCode": 0, "signal": "", "stdout": "", "stderr": "",
			"executionTime": took.Milliseconds(), "shellId": id, "pid": t.Pid,
			"backgroundReason": "SHELL_BACKGROUND_REASON_USER_REQUEST"},
			"isBackground": true, "terminalsFolder": dir}}
}

// await is what a run does once the agent's turns are over: it waits for the
// background commands to end, and says so on the stream for each (a
// task_notification), as cursor-agent -p was recorded doing before its result.
func (s *session) await(ctx context.Context) {
	wctx, cancel := tasks.WaitCeiling(ctx, tasks.DefaultWaitCeiling)
	defer cancel()
	for _, t := range s.bg.launched {
		select {
		case <-t.Done():
			tasks.Conclude(s.bg.reg, t, notices{s})
		case <-wctx.Done():
		}
	}
}

// notices writes what the stream shows of a task: only its end.
type notices struct{ s *session }

func (notices) Changed([]*tasks.Task)       {}
func (notices) Started(*tasks.Task)         {}
func (notices) Updated(*tasks.Task, string) {}
func (n notices) Notified(t *tasks.Task) {
	status := "success"
	if t.Status() != tasks.Completed {
		status = string(t.Status())
	}
	n.s.forward(jsonLine(map[string]any{
		"type": "system", "subtype": "task_notification", "task_id": t.ID, "status": status,
		"title": t.Description, "session_id": n.s.id, "timestamp_ms": time.Now().UnixMilli()}))
}
