		binary = filepath.Join(tmp, "a10n-cursor-mock")
		build := exec.Command("go", "build", "-o", binary, "./cursor-mock")
		build.Dir = root
		if out, err := build.CombinedOutput(); err != nil {
			fmt.Fprintf(os.Stderr, "e2e: build failed: %v\n%s\n", err, out)
			os.Exit(1)
		}
	}
	os.Exit(m.Run())
}

