package runner

import (
	"context"
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"strconv"
	"sync"
	"time"

	"github.com/sloprail/harness-mocks/internal/tasks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// unifiedExec is the commands a run started with a yield time (Codex's
// exec_command), which are still running after it: the registry that holds
// them, and the calls whose command is still running.
type unifiedExec struct {
	reg *tasks.Registry
	mu  sync.Mutex
	// running are the ids of the calls that yielded with their command still
	// running; files are the temporary files the commands print to.
	running map[string]bool
	files   []string
}

func newUnifiedExec() *unifiedExec {
	return &unifiedExec{reg: tasks.NewRegistry(), running: map[string]bool{}}
}

// close ends the run's commands that are still running: Codex does not wait
// for them, they die with the run (recorded: runs/background-bash-start).
func (u *unifiedExec) close() {
	u.reg.Shutdown()
	for _, f := range u.files {
		os.Remove(f)
	}
}

func (u *unifiedExec) stillRunning(callID string) bool {
	u.mu.Lock()
	defer u.mu.Unlock()
	return u.running[callID]
}

// yieldTime is how long a call asks to wait for its command before the call
// returns whether or not it has ended: its yield_time_ms; zero when it has none.
func yieldTime(c toolcall.Call) time.Duration {
	var in struct {
		Yield float64 `json:"yield_time_ms"`
	}
	_ = json.Unmarshal(c.Input, &in)
	return time.Duration(in.Yield * float64(time.Millisecond))
}

// runYielding runs a command that has a yield time, as Codex's unified exec
// does (recorded: runs/background-bash-start). The command is started on its
// own, not bound to the call. If it ends within the yield time the call returns
// its output like any command; if not, the call returns at once with a receipt,
// {chunk_id, wall_time_seconds, session_id, original_token_count, output}: the
// session id of the running command and what it has printed so far, and no file
// its output goes to. The command goes on running while the agent works; it is
// shown started on the event stream and never completed, and it is ended with
// the run. A call whose command is still running fires no PostToolUse.
//
// sr:provides background-bash/codex
// sr:docs https://developers.openai.com/codex/hooks#tool-coverage
func (h toolHost) runYielding(ctx context.Context, c toolcall.Call, cmd string, wait time.Duration) toolcall.Result {
	start := time.Now()
	id := h.events.CommandStarted(cmd)
	out, err := os.CreateTemp("", "codex-unified-exec-*")
	if err != nil {
		return toolcall.Result{Output: err.Error(), Failed: true}
	}
