func (h toolHost) Execute(ctx context.Context, c toolcall.Call) toolcall.Result {
	cmd := command(c)
	id := h.events.CommandStarted(cmd)
	var r tools.BashResult
	if y := yieldTime(c); y > 0 {
		var running bool
		if r, running = h.runYielding(cmd, y); running {
